INSERT INTO cases (id, title, area_id, summary, mission, context, content, status, island_order) VALUES
('am-simplificado', 'Asset Management: decisões dentro do mandato', 'asset-management', 'Avalie três decisões de carteira considerando retorno, risco, liquidez e as regras do fundo.', 'Recomendar apenas operações compatíveis com o mandato do fundo.', $$Você é analista júnior do Fundo Horizonte. Sua gestora pede recomendações independentes; cada análise já aprovou os demais critérios e você deve resolver a pendência indicada. Todos os nomes, instituições e números são fictícios.$$,
INSERT INTO checkpoints (id, case_id, "order", stage, title, description, points, task_ids) VALUES
('am-cp-1','am-simplificado',1,'entenda','O trabalho em Asset Management','Conheça mandato, liquidez, risco e diversificação.',15,'[]'),('am-cp-2','am-simplificado',2,'situacao','Liquidez da Aurora','Verifique se o título cabe na necessidade de caixa.',30,'["am-task-aurora"]'),('am-cp-3','am-simplificado',3,'situacao','A carteira concentrada','Calcule a concentração após a compra.',35,'["am-task-luar"]'),('am-cp-4','am-simplificado',4,'defesa','Reabra a análise','Explique o que mudaria sua recomendação.',40,'["am-task-defesa"]'),
('cr-cp-1','cr-simplificado',1,'entenda','O trabalho em Crédito e Risco','Conheça capacidade de pagamento, garantias e perdas.',15,'[]'),('cr-cp-2','cr-simplificado',2,'situacao','Parcela apertada','Avalie a capacidade de pagamento da proposta.',30,'["cr-task-parcela"]'),('cr-cp-3','cr-simplificado',3,'situacao','Garantia insuficiente','Avalie a cobertura recuperável da garantia.',35,'["cr-task-garantia"]'),('cr-cp-4','cr-simplificado',4,'defesa','Reabra a análise','Explique qual evidência mudaria a decisão.',40,'["cr-task-defesa"]'),
('qt-cp-1','quant-simplificado',1,'entenda','O laboratório quant','Conheça validação, custos e risco de cauda.',15,'[]'),('qt-cp-2','quant-simplificado',2,'situacao','O backtest impressionante','Identifique o risco de uma estratégia muito ajustada ao passado.',30,'["qt-task-backtest"]'),('qt-cp-3','quant-simplificado',3,'situacao','O modelo de previsão','Escolha a divisão correta dos dados.',35,'["qt-task-modelo"]'),('qt-cp-4','quant-simplificado',4,'defesa','Reabra o experimento','Explique qual evidência validaria o uso do modelo.',40,'["qt-task-defesa"]')
INSERT INTO tasks (id, case_id, checkpoint_id, title, prompt, fields, support_data, answer_key) VALUES
('am-task-aurora','am-simplificado','am-cp-2','Título Aurora',$$O fundo precisa transformar R$ 3 milhões em caixa em até 30 dias. Há R$ 2,4 milhões seguros; a compra usa R$ 800 mil. O título vence em três anos e não tem comprador nem preço garantidos em 30 dias. Você recomenda comprar?$$,$$[{"id":"decisao","tipo":"opcao","rotulo":"Recomenda comprar?","obrigatorio":true,"opcoes":["Sim","Não"]},{"id":"justificativa","tipo":"texto","rotulo":"Justifique com os fatos apresentados.","obrigatorio":true,"limiteCaracteres":320}]$$::jsonb,NULL,$${"gabarito":{"decisao":"Não"},"criterio":"A compra deixa R$ 1,6 milhão seguro frente à necessidade de R$ 3 milhões; revenda incerta não é liquidez garantida."}$$::jsonb),
('am-task-luar','am-simplificado','am-cp-3','Banco Luar',$$O patrimônio é R$ 20 milhões; a exposição atual ao emissor é R$ 2,4 milhões. A compra proposta é R$ 900 mil e o limite do mandato é 15%. Qual a concentração final e você executa integralmente?$$,$$[{"id":"concentracao","tipo":"opcao","rotulo":"Concentração após a compra","obrigatorio":true,"opcoes":["12%","15%","16,5%","20%"]},{"id":"decisao","tipo":"opcao","rotulo":"Executa integralmente?","obrigatorio":true,"opcoes":["Sim","Não"]},{"id":"justificativa","tipo":"texto","rotulo":"Justifique sua decisão.","obrigatorio":true,"limiteCaracteres":320}]$$::jsonb,NULL,$${"gabarito":{"concentracao":"16,5%","decisao":"Não"},"criterio":"R$ 3,3 milhões representam 16,5% e excedem o teto de R$ 3 milhões."}$$::jsonb),
('am-task-defesa','am-simplificado','am-cp-4','O que mudaria?',$$Que mudança concreta permitiria reavaliar a compra do título Aurora? E como ajustar a operação do Banco Luar para respeitar o mandato?$$,$$[{"id":"aurora","tipo":"texto","rotulo":"Aurora","obrigatorio":true,"limiteCaracteres":600},{"id":"luar","tipo":"texto","rotulo":"Banco Luar","obrigatorio":true,"limiteCaracteres":600}]$$::jsonb,NULL,$${"criterio":"Aceitar caixa seguro suficiente, resgate garantido ou redução de operação; no Luar, compra de até R$ 600 mil ou redução anterior da posição."}$$::jsonb),
('cr-task-parcela','cr-simplificado','cr-cp-2','Parcela apertada',$$Uma proposta pede parcela mensal de R$ 1.800. A renda líquida verificada é R$ 4.000 e as obrigações atuais somam R$ 1.700. A política limita obrigações a 60% da renda. Você recomenda aprovar nas condições atuais?$$,$$[{"id":"decisao","tipo":"opcao","rotulo":"Recomenda aprovar?","obrigatorio":true,"opcoes":["Sim","Não"]},{"id":"justificativa","tipo":"texto","rotulo":"Justifique com os números.","obrigatorio":true,"limiteCaracteres":320}]$$::jsonb,NULL,$${"gabarito":{"decisao":"Não"},"criterio":"As obrigações seriam R$ 3.500, ou 87,5% da renda, acima do limite."}$$::jsonb),
('cr-task-garantia','cr-simplificado','cr-cp-3','Garantia insuficiente',$$Uma operação de R$ 300 mil tem imóvel dado em garantia avaliado em R$ 320 mil, mas a política reconhece somente 60% do valor após custos e prazo de recuperação. A cobertura reconhecida atende a operação?$$,$$[{"id":"decisao","tipo":"opcao","rotulo":"A garantia cobre a operação?","obrigatorio":true,"opcoes":["Sim","Não"]},{"id":"justificativa","tipo":"texto","rotulo":"Justifique com o valor recuperável.","obrigatorio":true,"limiteCaracteres":320}]$$::jsonb,NULL,$${"gabarito":{"decisao":"Não"},"criterio":"60% de R$ 320 mil é R$ 192 mil, abaixo da exposição de R$ 300 mil."}$$::jsonb),
('cr-task-defesa','cr-simplificado','cr-cp-4','O que mudaria?',$$Qual informação verificável permitiria reavaliar uma das duas propostas?$$,$$[{"id":"resposta","tipo":"texto","rotulo":"Sua resposta","obrigatorio":true,"limiteCaracteres":600}]$$::jsonb,NULL,$${"criterio":"Nova renda comprovada, redução da parcela, coobrigado ou garantia recuperável suficiente são caminhos aceitáveis."}$$::jsonb),
('qt-task-backtest','quant-simplificado','qt-cp-2','Backtest impressionante',$$Uma estratégia teve ótimo resultado no histórico, mas escolheu seus parâmetros depois de testar repetidamente o mesmo período. Custos de negociação ainda não foram descontados. Você recomenda colocá-la em produção?$$,$$[{"id":"decisao","tipo":"opcao","rotulo":"Recomenda colocar em produção?","obrigatorio":true,"opcoes":["Sim","Não"]},{"id":"justificativa","tipo":"texto","rotulo":"Justifique com os riscos do teste.","obrigatorio":true,"limiteCaracteres":320}]$$::jsonb,NULL,$${"gabarito":{"decisao":"Não"},"criterio":"Há risco de overfitting e faltam custos e validação fora da amostra."}$$::jsonb),
('qt-task-modelo','quant-simplificado','qt-cp-3','Modelo de previsão',$$Para prever o mês seguinte, qual divisão de dados evita vazamento temporal?$$,$$[{"id":"divisao","tipo":"opcao","rotulo":"Escolha a divisão","obrigatorio":true,"opcoes":["Misturar todas as datas aleatoriamente","Treinar em dados antigos e testar em período posterior","Usar o resultado futuro como variável","Testar no mesmo período usado para ajustar parâmetros"]}]$$::jsonb,NULL,$${"gabarito":{"divisao":"Treinar em dados antigos e testar em período posterior"}}$$::jsonb),
('qt-task-defesa','quant-simplificado','qt-cp-4','O que mudaria?',$$Que evidência concreta faria você confiar mais no backtest antes de usar dinheiro real?$$,$$[{"id":"resposta","tipo":"texto","rotulo":"Sua resposta","obrigatorio":true,"limiteCaracteres":600}]$$::jsonb,NULL,$${"criterio":"Validação fora da amostra, custos descontados, regras congeladas e teste em período novo são evidências aceitáveis."}$$::jsonb)
